    lc=min(nzcolors,key=lambda v:cc[v]); mc=max(nzcolors,key=lambda v:cc[v])
    F={}
    F['nz']=lambda c: sum(v!=0 for v in c)
    F['z']=lambda c: sum(v==0 for v in c)
    F['has_lc']=lambda c: lc in c
    F['has_mc']=lambda c: mc in c
    F['allzero']=lambda c: all(v==0 for v in c)
    F['anynz']=lambda c: any(v!=0 for v in c)
    F['majz']=lambda c: sum(v==0 for v in c)>=len(c)/2
    for v in nzcolors:
        F[f'c{v}']=(lambda vv: lambda c: sum(x==vv for x in c))(v)
    F['adjh']=lambda c: sum(1 for k in range(len(c)-1) if c[k]!=0 and c[k+1]!=0 and (k+1)%max(1,(len(c)//3 if len(c)%3==0 else len(c)))!=0)  # junk
    F['nzc']=lambda c: len(set(v for v in c if v!=0))
    F['mx']=lambda c: max(c) if c else 0
    return F

