    h=len(d); w=len(d[0]); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if d[i][j]!=0 and (i,j) not in seen:
                col=d[i][j]; st=[(i,j)]; seen.add((i,j)); cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and d[x][y]==col and (x,y) not in seen:
                            seen.add((x,y)); st.append((x,y))
                out.append((col,cells))
    return out
