from math import floor,ceil
def scale_shape(cells,mode):
    rs=[i for i,j in cells]; cs=[j for i,j in cells]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    h=r1-r0; w=c1-c0
    def mp(x,lo,L):
        if L==0: return 1
        if mode=='round': return round((x-lo)*2/L)
        if mode=='floor': return int((x-lo)*2//L)
        return ceil((x-lo)*2/L)
    return {(mp(i,r0,h),mp(j,c0,w)) for i,j in cells}

